ALTER TABLE orders ADD COLUMN amount_cents bigint;

CREATE OR REPLACE FUNCTION orders_set_amount_cents()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.amount_cents := (NEW.amount * 100)::bigint;
    RETURN NEW;
END;
$$;

CREATE TRIGGER orders_ins_amount_cents
BEFORE INSERT ON orders
FOR EACH ROW
EXECUTE FUNCTION orders_set_amount_cents();

CREATE TRIGGER orders_upd_amount_cents
BEFORE UPDATE ON orders
FOR EACH ROW
EXECUTE FUNCTION orders_set_amount_cents();

WITH params AS (
    SELECT min(id) AS min_id, max(id) AS max_id, 10000 AS batch_size FROM orders
),
batches AS (
    SELECT generate_series(0, (max_id - min_id) / batch_size) AS batch_num, min_id, max_id, batch_size FROM params
)
SELECT format(
    'UPDATE orders SET amount_cents = (amount * 100)::bigint WHERE amount_cents IS NULL AND id BETWEEN %s AND %s;',
    (batch_num * batch_size + min_id)::bigint,
    LEAST(((batch_num + 1) * batch_size - 1 + min_id)::bigint, max_id)
)
FROM batches
\gexec

ALTER TABLE orders ADD CONSTRAINT orders_amount_cents_not_null CHECK (amount_cents IS NOT NULL) NOT VALID;
ALTER TABLE orders VALIDATE CONSTRAINT orders_amount_cents_not_null;
ALTER TABLE orders ALTER COLUMN amount_cents SET NOT NULL;
```

